export const getListSharedMicrotaskEvidenceUrl = (id: number,
    params: ListSharedMicrotaskEvidenceParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/employer/micro-evidence/${id}?${stringifiedParams}` : `/api/employer/micro-evidence/${id}`
}

